/* New Meridian processes (v8): Benefits organization, Bank supervision, Cash & payment operations. Pure data, no imports. */
export const MORE = [

 /* ---------------- Benefits organization ---------------- */
 {fn:'benefits', area:'ben-inquiries',
  proc:{id:'openenrol', name:'Open enrolment communications', d:'List what changed in the plans, write the season’s emails and FAQ, keep the FAQ current as questions arrive, and remind people who have not enrolled.', rating:3, why:'One busy season a year with a measured surge of questions. Tracking the questions and drafting help; the reminders are a rule, and the yearly list of changes is too small for a tool.'},
  intro:'Every autumn the health and retirement plans change, and 2,400 employees and 3,800 retirees have five weeks to choose. What the emails say decides how many of the 6,000 questions arrive. Walk the season from the carriers’ renewal letters to the last reminder.',
  steps:[
  {n:'Work out what changed this year', who:'Benefits manager', vol:'Once a year, 14 carriers', sys:'Carrier renewal letters, plan documents, last year’s change list',
   notes:'In August the carriers send renewal letters with new premiums, deductibles and covered services. The benefits manager compares them with last year’s plan documents and writes a two-page list of what changed. Every email and FAQ answer is built from that list.',
   pain:'Four days of one person’s time, once a year. Last year a change to the dental waiting period was missed until employees asked about it.',
   p:'summarize text low mid', alt:'shape:check', best:'summarize', ok:'extract retrieve', auto:'review', autoOk:'assist',
   why:'The general assistant staff already have can compare this year’s documents with last year’s and list the differences for the manager to check. At once a year, a dedicated tool would never pay back.',
   disc:[['Once a year','The comparison happens once a year and takes four days.','Volume: use the general assistant, not a new tool.'],['The missed change','The dental change was in a carrier letter, not in the plan document.','Keep: check every carrier letter line by line against the list.']],
   fv:'high low', reality:'Easy, and too small to build anything for. A checklist of where changes hide is the right size.',
   metric:'Days to a signed-off change list, and changes found after the emails go out', g:'sampling', hyp:'A complete change list in two days, with nothing found late.', data:'This year’s and last year’s plan documents, the carrier renewal letters.'},
  {n:'Draft the enrolment emails and FAQ', who:'Benefits communications specialist', vol:'About 12 emails, a 60-question FAQ and a retiree letter each year', sys:'Word, email system, intranet, last year’s FAQ',
   notes:'From the change list, the specialist writes the announcement, the weekly reminders, the FAQ for the intranet and a printed letter for retirees. The benefits manager and the carriers check every piece before it goes out, because it tells people what they will pay and what is covered.',
   pain:'Three weeks of writing and checking. Last year a premium table in one email was wrong, and 400 people wrote in about it.',
   p:'draft text mid high', alt:'stakes:mid', best:'draft', ok:'retrieve', auto:'assist', autoOk:'review',
   why:'Draft each piece from the signed-off change list and last year’s wording, for the specialist to rewrite. Every figure is checked against the carrier’s rate sheet before anything is sent, because people choose their cover on these words.',
   disc:[['The wrong table','The premium error came from copying last year’s table and editing it by hand.','Rule: premium tables come straight from the rate sheet, never retyped or generated.'],['Plain words cut questions','The FAQ answers that drew the most follow-up questions were the longest ones.','Value: shorter, plainer answers shrink the surge.']],
   fv:'high mid', reality:'Easy to do, with a medium prize. The checking stays with people because what the emails say shapes every choice.',
   metric:'Days to write the season’s materials, and questions caused by errors in them', g:'sampling logging escalation', hyp:'The season’s materials written in a week, with no wrong figures.', data:'The change list, the carrier rate sheets, last year’s emails and FAQ.'},
  {n:'Track the questions and update the FAQ', who:'Benefits counsellors', vol:'About 6,000 questions in five weeks', sys:'Shared mailbox, phone log, intranet FAQ',
   notes:'Counsellors answer questions as they arrive. Once a week they are meant to say which topics are growing so the FAQ can be fixed. In practice they go on memory, because nobody has time to read back through 1,200 emails a week.',
   pain:'The FAQ is updated twice in the season, both times late. The same confusion runs for weeks when one clear sentence could have stopped it.',
   p:'summarize text high low', alt:'shape:route', best:'summarize classify', ok:'retrieve draft', auto:'review', autoOk:'auto',
   why:'Group each week’s questions by topic, show which topics are growing with example questions, and point to the FAQ answer that is causing them. A counsellor decides what to change.',
   disc:[['Forty questions','Forty questions make up most of the season, so the topics are known in advance.','Data: last year’s mailbox is a ready test set.'],['Personal details','Many emails mention diagnoses and family details.','Privacy: count and group the questions; keep personal details out of the weekly report.']],
   fv:'high mid', reality:'Quick to do on email that already exists. Medium value: fewer repeat questions and an FAQ that keeps up.',
   metric:'Days from a new confusion appearing to a fixed FAQ answer, and repeat questions per topic', g:'privacy sampling', hyp:'Every confusing answer fixed within a week of it appearing.', data:'The season’s mailbox and phone log, the FAQ, last year’s questions.'},
  {n:'Remind people who have not enrolled', who:'Benefits specialists', vol:'About 1,500 reminders a season', sys:'Enrolment portal, HR system, email',
   notes:'Some choices lapse if nobody acts, such as the health spending account. In the last two weeks, specialists export the list of people with no election, compare it with the HR list in a spreadsheet and email each one.',
   pain:'Two days of spreadsheet work in each of the last two weeks. Last year 90 people lost their spending account because the reminder went to an old address.',
   p:'coordinate structured high mid', best:'rules', ok:'agent', auto:'auto', autoOk:'review',
   why:'Who has not enrolled is already a field in the portal. Send reminders on a schedule from the portal and the HR list, with no spreadsheet and no AI.',
   disc:[['Old addresses','Retirees’ email addresses come from a list last cleaned three years ago.','Fix first: use the pension system’s current contact details, and post a letter where there is no email.'],['The portal can do it','The enrolment portal has a reminder feature that was never switched on.','Feasibility: a setting, not a project.']],
   fv:'high mid', reality:'Plain engineering on data that already exists. Medium value: hours saved, and nobody losing cover by accident.',
   metric:'People who lose a benefit for not enrolling, and specialist hours on reminders', g:'logging rollback', hyp:'Everyone without an election reminded three times, and no lapses from an old address.', data:'Portal elections, the HR and pension contact lists.'},
 ]},

 {fn:'benefits', area:'ben-pensions',
  proc:{id:'pensionest', name:'Pension estimate requests', d:'Collect the request, assemble the service and salary history, calculate the estimate and check it before it goes out.', rating:3, why:'Steady volume, a fixed formula and a number people plan their lives on. The gains are a better form, clean records and one owned calculator; the final check stays with a person.'},
  intro:'Staff thinking about retirement ask what their pension would be if they left on a given date. The formula is fixed, but the records behind it are scattered, and the answer shapes a life decision. Walk a request from email to estimate.',
  steps:[
  {n:'Collect the request details', who:'Pension specialists', vol:'About 1,100 requests a year', sys:'Email, PDF request form',
   notes:'Staff ask by email or with a PDF form. To calculate, a specialist needs the retirement date, whether to count unused sick leave, which survivor option to use and whether a part-time period should be bought back. Most requests leave at least one of these out, so the specialist writes back.',
   pain:'Two requests in three need at least one more email, and a request waits nine days on average before work starts.',
   p:'coordinate text mid mid', alt:'shape:extract', best:'fix', ok:'rules agent', auto:'auto', autoOk:'review',
   why:'Replace the PDF with a short form on the benefits portal that asks every question the calculation needs and will not submit without them. The chasing disappears, and no AI is needed.',
   disc:[['The form asks too little','The PDF form asks for a name and a date, and nothing else the calculation needs.','Fix first: add the four missing questions, with a line explaining each.'],['People ask twice','A fifth of requests are a second estimate for a different date.','Let the form ask for up to three dates at once.']],
   fv:'high mid', reality:'A process fix that removes most of the waiting. Quick, and it helps every step after it.',
   metric:'Requests needing a follow-up email, and days before work starts', g:'logging', hyp:'Nine requests in ten complete on arrival.', data:'The calculation’s inputs, and a year of requests with the follow-up emails they needed.'},
  {n:'Assemble the service and salary history', who:'Pension specialists', vol:'About 1,100 histories a year', sys:'Pension system, HR system, paper record cards',
   notes:'The specialist gathers the person’s service dates, part-time periods, unpaid leave and salary history. Since 2004 this sits in the HR system. Before that it is on paper record cards in the records room, which are fetched and read by hand.',
   pain:'About two hours per history for long-serving staff, most of it on the paper cards. Some cards are handwritten and hard to read.',
   p:'extract media mid mid', alt:'input:structured', best:'extract', ok:'vision rules', auto:'review',
   why:'Scan the old record cards once and read them into the pension system, with a specialist confirming each card. After that, a history is assembled from systems in minutes. Errors here are caught at the final check, so the stakes at this step are medium.',
   disc:[['A one-time job','About 900 current staff have service before 2004, so the paper is finite.','Prepare: digitise the cards once, and the problem is gone for good.'],['Handwriting','About a third of the older cards are handwritten.','Expect lower confidence on those; a specialist confirms every card.']],
   fv:'mid high', reality:'High value, because every estimate for long-serving staff waits on paper. Medium feasibility until the cards are scanned.',
   metric:'Hours per history, and histories corrected at the final check', g:'threshold privacy sampling', hyp:'Any history assembled in ten minutes once the cards are in the system.', data:'Scanned record cards, the HR and pension records, a sample of histories checked by hand.'},
  {n:'Calculate the estimate', who:'Pension specialists', vol:'About 1,100 estimates a year', sys:'Spreadsheet calculator, plan rules',
   notes:'The pension is a fixed formula: years of service times an accrual rate times the final average salary, reduced for early retirement and adjusted for the survivor option. Specialists use a spreadsheet calculator built in 2011 by someone who has since retired.',
   pain:'Nobody owns the calculator. It was patched by hand for the 2019 plan change, and two specialists now keep their own versions.',
   p:'draft structured mid high', alt:'shape:predict', best:'rules', ok:'fix', auto:'review', autoOk:'assist',
   why:'The formula is written in the plan rules, so the calculation is a rule. Build it once in the pension system, test it against past estimates, and give it one owner. Producing the number with an LLM would add risk for nothing.',
   disc:[['The unused module','The pension system has a calculation module the Bank never set up, because it could not handle service transferred in from other public plans.','Feasibility: configure the module and keep a short manual path for transfers.'],['Two versions','The two specialists’ spreadsheets give different answers for part-time service.','Rule: one calculator, tested against the plan rules, with a named owner.']],
   fv:'high high', reality:'Plain engineering with a high prize: a number people plan their retirement on, calculated the same way every time.',
   metric:'Estimates that differ from the pension finally paid, and minutes per calculation', g:'logging rollback sampling', hyp:'Every estimate calculated the same way, in minutes, and matching the pension finally paid.', data:'The plan rules, the spreadsheet calculator, five years of estimates with the pensions finally paid.'},
  {n:'Check the estimate before it goes out', who:'Senior pension specialist', vol:'About 1,100 checks a year', sys:'Pension system, estimate letter, checklist',
   notes:'A second specialist re-checks every estimate: the service dates, the salary used, the options and the arithmetic. People resign, sell houses and plan their finances on this letter, so nothing goes out unchecked.',
   pain:'The senior specialist re-does most of the calculation by hand, which adds a week. One estimate in forty is still corrected after it is sent.',
   p:'check structured mid high', best:'anomaly', ok:'rules recommend', auto:'assist',
   why:'Once the calculator is owned and tested, the check can focus: flag estimates that differ from the person’s last estimate or from similar staff, and the inputs most often wrong. The senior specialist still signs every letter.',
   disc:[['A life decision','People have resigned on the strength of an estimate.','Risk: a person signs every estimate; the flags only point where to look.'],['Where errors come from','Most corrections trace back to part-time periods and unpaid leave.','Check those inputs first, every time.']],
   fv:'mid high', reality:'High value and high stakes. Assist only, and worth it once the calculator is fixed.',
   metric:'Days added by the check, and estimates corrected after sending', g:'logging escalation sampling', hyp:'The check cut from a week to a day, with fewer corrections after sending.', data:'Past estimates with their corrections, each person’s earlier estimates, the plan rules.'},
 ]},

 {fn:'benefits', area:'ben-billing',
  proc:{id:'lifeevents', name:'Life-event changes', d:'Hear about a marriage, birth, divorce or move in time, explain what it changes, decide eligibility and the deadline, and split pensions on divorce.', rating:3, why:'Steady volume with a deadline people miss. The first win is hearing about events in time; drafting the explanation helps; eligibility calls stay with specialists, and pension splits are too rare for a tool.'},
  intro:'A marriage, a birth, a divorce or a move can change an employee’s health cover, beneficiaries and pension, and most changes must be made within 31 days. Many people find out about the deadline too late. Walk a life event from the news reaching the Bank to a decision on the change.',
  steps:[
  {n:'Hear about the event in time', who:'Benefits specialists', vol:'About 1,300 life events a year', sys:'HR system, payroll, email',
   notes:'Employees must tell benefits within 31 days of a marriage, birth, divorce or move. Many tell their manager, HR or payroll instead, through a parental leave request or a change of address, and assume the news reaches benefits. It does not.',
   pain:'One event in six is reported after the 31 days, and the person must wait until open enrolment to add a spouse or a baby to their cover.',
   p:'coordinate structured mid mid', alt:'input:text', best:'fix', ok:'rules agent', auto:'auto', autoOk:'review',
   why:'The Bank already hears about most events, just in the wrong place. Add one question and the deadline to the parental leave and change-of-address forms, and send benefits a notice whenever they are used. A process change, not an AI tool.',
   disc:[['Already known','Most late births were in the HR system as parental leave weeks before benefits heard.','Fix first: connect the forms people already use to benefits.'],['Nobody knows the rule','Few employees know about the 31-day rule.','Put the deadline on every form where a life event shows up.']],
   fv:'high high', reality:'A process fix with a high prize: no baby left without cover because a form went to the wrong team.',
   metric:'Events reported after 31 days', g:'logging privacy', hyp:'Fewer than one event in fifty reported late.', data:'The HR and payroll forms, and a year of late events with where the news first arrived.'},
  {n:'Explain what the event changes', who:'Benefits specialists', vol:'About 1,300 replies a year', sys:'Email, life-events guide, HR system',
   notes:'For each event the specialist writes to the person explaining what they can change, which documents to send and the deadline. A 30-page life-events guide covers each event type, and each reply is written by hand from it.',
   pain:'Forty minutes per reply. Replies for the same event differ between specialists, and a fifth leave out a document, so the person has to send something twice.',
   p:'draft text mid mid', alt:'shape:lookup', best:'draft retrieve', ok:'converse', auto:'review',
   why:'Draft the reply from the life-events guide and the person’s current cover: what can change, which documents, and by what date. The specialist checks and sends it.',
   disc:[['One current guide','The life-events guide is current and covers every event type.','Data: ready to draft from.'],['Divorce and death are different','Replies about a divorce or a death depend on court orders and wills.','Keep: those go straight to a senior specialist.']],
   fv:'high mid', reality:'A quick win from a good guide. Medium value: specialist time saved and fewer documents sent twice.',
   metric:'Minutes per reply, and documents requested a second time', g:'sampling escalation privacy', hyp:'Complete, consistent replies within a day, in ten minutes each.', data:'The life-events guide, a year of replies, current cover from the HR system.'},
  {n:'Decide eligibility and the deadline', who:'Benefits specialists and the benefits manager', vol:'About 1,300 cases a year, 150 of them unclear', sys:'HR system, plan documents, case notes',
   notes:'When the documents arrive, the specialist decides whether the new dependant is eligible and the change is in time. Most cases are clear. The rest are stepchildren, guardianships, partners without a marriage certificate and reports a few days late, which go to the manager.',
   pain:'Unclear cases wait two weeks for the manager, and similar cases have been decided differently.',
   p:'decide text mid high', alt:'shape:check', best:'recommend', ok:'retrieve summarize', auto:'assist',
   why:'Set out the plan rule, the documents received, the dates and similar past decisions for each unclear case. The specialist or manager decides, because the answer decides whether a family has cover.',
   disc:[['Past rulings in email','Past rulings on unclear cases are in the manager’s email, not in a log.','Capture decisions in a short log so precedent can be found.'],['A family’s cover','A refusal can leave a child without health cover.','Risk: a person decides every case, and every refusal is explained in writing.']],
   fv:'mid high', reality:'High value and high stakes. Assist only, once past rulings are logged.',
   metric:'Days to decide unclear cases, and similar cases decided differently', g:'logging escalation bias privacy', hyp:'Unclear cases decided within three days, consistently.', data:'The plan eligibility rules, past rulings, the case documents.'},
  {n:'Split a pension after a divorce', who:'Senior pension specialist and the plan’s lawyer', vol:'About 15 court orders a year', sys:'Court orders, pension system, outside actuary',
   notes:'A divorce can come with a court order that gives part of the pension to the former spouse. The senior specialist and the plan’s lawyer read each order, check that the plan can carry it out and ask an actuary to value the split.',
   pain:'Each order takes about three weeks, mostly waiting for the lawyer and the actuary. Orders drafted by the couple’s own lawyers often cannot be carried out as written.',
   p:'decide text low high', best:'recommend', ok:'retrieve summarize', auto:'assist',
   why:'Fifteen orders a year, each a legal judgment. A model order that divorce lawyers can copy, published on the Bank’s website, would prevent more problems than any tool.',
   disc:[['Fifteen a year','About fifteen orders arrive a year.','Volume: not worth a tool.'],['Orders that cannot work','A third of orders ask for something the plan cannot do.','Publish a model order and a one-page guide for divorce lawyers.']],
   fv:'high low', reality:'Easy to help with, but too rare and too legal for a tool. A model order is the right size.',
   metric:'Orders that cannot be carried out as written, and weeks per order', g:'logging escalation', hyp:'Most orders arrive in a form the plan can carry out.', data:'Past orders and the plan rules.'},
 ]},

 /* ---------------- Bank supervision ---------------- */
 {fn:'supervision', area:'sup-exams',
  proc:{id:'examreport', name:'Drafting examination reports', d:'Gather the findings from the workpapers, draft the report of examination and check each finding against the Bank’s standard before the report goes to the board.', rating:3, why:'About 160 reports a year, each a week or more of senior time. Drafting help is real, but every word is a supervisory judgment sent to a bank’s board, so the writing stays in assist mode.'},
  intro:'Every examination ends in a report to the bank’s board of directors: the ratings, the findings and what the bank must fix. Boards act on every word, and banks can appeal. Walk a report from the last workpaper to the board.',
  steps:[
  {n:'Gather the findings from the workpapers', who:'Examiners in charge', vol:'About 160 examinations a year, 40 to 120 workpapers each', sys:'Workpaper system, findings tracker, Word',
   notes:'After fieldwork, the examiner in charge reads through the team’s workpapers to pull together every finding, its evidence and the conclusion of each review area. Six or seven examiners write the workpapers, each in their own style.',
   pain:'Three to four days per examination, and findings in late workpapers are sometimes missed until quality review.',
   p:'summarize text mid high', alt:'shape:extract', best:'summarize', ok:'extract retrieve', auto:'assist',
   why:'Summarise each workpaper’s conclusion and findings into one list with references, for the examiner in charge to check. Which findings matter, and how much, stays the examiner’s judgment.',
   disc:[['Confidential supervisory information','Workpapers are confidential supervisory information.','Data: the tool runs only inside the Bank’s approved environment.'],['Conclusions are not marked','Only some examiners write a clear conclusion at the end of each workpaper.','Prepare: a conclusion box in the workpaper template makes summaries more reliable.']],
   fv:'mid high', reality:'High value on the path to every report. Medium feasibility in the approved environment, and assist only.',
   metric:'Days from end of fieldwork to a findings list, and findings missed until quality review', g:'privacy logging sampling', hyp:'A complete findings list the day after fieldwork ends.', data:'Workpapers from past examinations with their final reports.'},
  {n:'Draft the report of examination', who:'Examiners in charge', vol:'About 160 reports a year, 20 to 40 pages each', sys:'Report template, Word, past reports',
   notes:'The examiner in charge writes the report: the ratings and why, each finding with its cause, what the bank must do and by when. Senior supervisors edit it, sometimes heavily, and the wording is argued over because the board will act on it and may appeal.',
   pain:'A week of writing and two rounds of editing per report. Reports with similar findings use very different words.',
   p:'draft text mid high', alt:'shape:decide', best:'draft', ok:'retrieve summarize', auto:'assist',
   why:'Draft the sections from the findings list and the approved wording of past findings, for the examiner to rewrite. The ratings, the findings and every sentence the board reads remain the examiner’s.',
   disc:[['Boards act on it','A bank’s board must answer every finding, and can appeal a rating.','Risk: assist only; nothing reaches the board that the examiner has not rewritten and signed.'],['Good examples exist','Senior supervisors keep a set of well-written past findings.','Data: retrieve those as models, not whole old reports.']],
   fv:'mid high', reality:'High value and high stakes. Assist mode, with the examiner rewriting every section.',
   metric:'Days from findings list to final report, and editing rounds per report', g:'privacy logging sampling escalation', hyp:'Writing cut from a week to three days, with fewer editing rounds.', data:'Past reports and findings, the report template, the senior supervisors’ model findings.'},
  {n:'Check each finding meets the standard', who:'Report editors', vol:'About 160 reports and 900 findings a year', sys:'Word, the Bank’s findings standard',
   notes:'The Bank’s standard says every finding must state the problem, its cause, the action required and a date. Two editors read each report against the standard before it is signed, and send it back when a part is missing.',
   pain:'One report in three comes back for a missing part, adding a week. Editors spend their time hunting for the date in each finding.',
   p:'check text mid mid', best:'extract', ok:'anomaly rules', auto:'review',
   why:'Pull the four parts out of each finding and flag those with a part missing, for the editor to confirm. This checks the shape of each finding, not the judgment in it.',
   disc:[['A written standard','The four-part standard is written down with examples.','Feasibility: a clear test to check against.'],['Earlier is better','Most missing parts are dates the examiner meant to add later.','Run the check when the draft is saved, not just before signing.']],
   fv:'high mid', reality:'A quick win against a written standard. Medium value: a week saved on a third of reports.',
   metric:'Reports returned for a missing part, and editor hours per report', g:'sampling logging', hyp:'No report returned for a missing part.', data:'The findings standard and a year of edited reports.'},
 ]},

 {fn:'supervision', area:'sup-exams',
  proc:{id:'qareview', name:'Quality review of examination workpapers', d:'Choose which examinations to review, check required procedures were done, trace each finding to its evidence and judge whether it holds.', rating:2, why:'About 40 reviews a year of long workpaper files. Procedure checks are rules and tracing is extraction once references follow one standard; the judgment on the evidence stays with the reviewer.'},
  intro:'Before a report goes to a bank’s board, a reviewer from outside the examination team checks that the work supports every finding. A finding that cannot be supported costs the Bank its standing with the bank. Walk a review from choosing the examination to signing it off.',
  steps:[
  {n:'Choose which examinations to review', who:'Quality review manager', vol:'Four times a year, about 40 of 160 examinations', sys:'Examination schedule, spreadsheet',
   notes:'Every quarter the manager picks which examinations to review: all of the largest banks, any with a rating change, and a sample of the rest. The rules are in the review manual, and the choice takes an afternoon.',
   pain:'Little measurable cost. Some examiners in charge have not been reviewed in three years.',
   p:'suggest structured low mid', alt:'shape:allocate', best:'recommend', ok:'rules', auto:'assist',
   why:'An afternoon a quarter, from rules already in the manual. Add each examiner’s review history to the spreadsheet so nobody goes three years unreviewed. No tool is needed.',
   disc:[['An afternoon a quarter','The choice takes about four hours, four times a year.','Volume: not worth a tool.'],['Coverage of people','The manual covers banks, not examiners.','Add a rule: every examiner in charge reviewed at least every two years.']],
   fv:'high low', reality:'Easy, and too small for a tool. One extra column is the fix.',
   metric:'Examiners in charge not reviewed in two years', g:'logging', hyp:'Every examiner in charge reviewed at least every two years.', data:'The examination schedule and the review history.'},
  {n:'Check required procedures were done', who:'Quality reviewers', vol:'About 40 reviews a year, 30 required procedures each', sys:'Examination system, review checklist',
   notes:'Each type of examination has required procedures, such as a minimum loan sample and a review of the bank’s internal audit. Each one has a sign-off field in the examination system. The reviewer works down a paper checklist, opening each field to see whether it was signed.',
   pain:'A day per review spent confirming sign-offs the system already holds.',
   p:'check structured mid mid', best:'rules', ok:'anomaly', auto:'auto', autoOk:'review',
   why:'Whether a required procedure was signed off is a field. A report from the examination system lists the gaps for every examination, not just the 40 reviewed. No AI is needed.',
   disc:[['Already in the system','Every required procedure has a sign-off field.','Feasibility: a report, not a project.'],['Signed is not done','A signed-off procedure can still be thin.','Keep: the report finds gaps; the reviewer still reads the work.']],
   fv:'high mid', reality:'Plain engineering on data that already exists, covering every examination.',
   metric:'Reviewer hours on procedure checks, and gaps found after the report is sent', g:'logging rollback', hyp:'Every examination checked for missing procedures before the report is drafted.', data:'The examination system’s sign-off fields and the list of required procedures.'},
  {n:'Trace each finding to its evidence', who:'Quality reviewers', vol:'About 40 reviews a year, 6 findings and 80 workpapers each', sys:'Workpaper system, draft report',
   notes:'For each finding in the draft report, the reviewer finds the workpapers that support it. References are typed by hand, such as “see loans tab” or “WP 4.2 (old numbering)”, so much of the time goes on finding the right page.',
   pain:'Two days per review, mostly searching. Broken references send reviewers back to the examiner.',
   p:'extract text mid mid', alt:'shape:lookup', best:'extract', ok:'retrieve', auto:'review',
   why:'Link each finding to the workpapers and pages that support it, and flag findings with no clear evidence. It works once references follow one standard; today half do not.',
   disc:[['References in free text','Half the references use an old numbering scheme or a nickname.','Prepare: one reference standard in the workpaper template.'],['Approved environment','Workpapers are confidential supervisory information.','Data: inside the Bank’s boundary only.']],
   fv:'mid high', reality:'High value: reviewers spend their time judging, not searching. Medium feasibility until references are standard.',
   metric:'Reviewer hours searching, and broken references per review', g:'threshold privacy sampling', hyp:'Searching cut from two days to half a day.', data:'Past reviews with their findings and the workpapers that supported them.'},
  {n:'Judge whether the evidence holds', who:'Quality reviewers', vol:'About 240 findings a year', sys:'Workpapers, draft report, review memo',
   notes:'The reviewer reads the evidence for each finding and judges whether it holds: enough loans sampled, the right conclusion drawn, a rating in line with similar banks. Disagreements are settled with the examiner in charge before the report goes out.',
   pain:'Reviews take three weeks, and reports wait for them.',
   p:'decide text mid high', best:'recommend', ok:'retrieve summarize', auto:'assist',
   why:'Show the evidence for each finding beside similar findings at other banks and how they were rated. The reviewer judges; a supervisory judgment is never handed to a tool.',
   disc:[['Consistency from memory','Reviewers compare ratings with similar banks from memory.','Retrieval over past findings makes the comparison real.'],['A judgment on a judgment','The review challenges an examiner’s supervisory judgment.','Risk: assist only, and every disagreement recorded.']],
   fv:'mid high', reality:'High value and high stakes. Assist only, once tracing is in place.',
   metric:'Weeks per review, and findings changed after the report is sent', g:'logging escalation bias', hyp:'Reviews done in a week, with ratings consistent across similar banks.', data:'Past findings with their ratings, review memos and outcomes.'},
 ]},

 {fn:'supervision', area:'sup-consumer',
  proc:{id:'complainttrends', name:'Complaint trend reporting', d:'Code each quarter’s complaints by issue, flag unusual rises, explain what lies behind them and report to examiners.', rating:3, why:'About 1,050 complaints a quarter, already in the case system. Coding and summarising fit well; flagging rises is blocked by missing customer numbers; the quarterly report is too small for its own tool.'},
  intro:'Each quarter, analysts look across about 1,050 complaints for problems no single complaint can show: a new fee at one bank, a rise in mortgage trouble across many. Examiners use the result to decide where to look. Walk a quarter.',
  steps:[
  {n:'Code each complaint by issue', who:'Consumer compliance analysts', vol:'About 1,050 complaints a quarter', sys:'Case system, issue list, spreadsheet',
   notes:'Intake codes each complaint by one of twelve broad products. Trends need finer issues: an overdraft fee, a closed account, a mortgage payment not credited. Two analysts read each narrative and add one of 60 issue codes in a spreadsheet.',
   pain:'Six analyst-days a quarter, and the two analysts code the same complaint differently about one time in five.',
   p:'route text high low', alt:'shape:extract', best:'classify', ok:'extract rules', auto:'review', autoOk:'auto',
   why:'Classify each narrative against the 60 issue codes, with a confidence score. Analysts check the uncertain ones and a sample of the rest.',
   disc:[['Three years coded','Three years of complaints already carry analysts’ issue codes.','Data: ready for testing.'],['Codes that overlap','Several issue codes overlap, which is why analysts disagree.','Fix first: merge the overlapping codes.']],
   fv:'high mid', reality:'A quick win on coded history. Medium value: analyst days saved and consistent codes.',
   metric:'Analyst days on coding, and agreement with a sample coded by hand', g:'threshold sampling', hyp:'Every complaint coded within a day of quarter end, more consistently than today.', data:'Three years of complaints with issue codes, the issue list.'},
  {n:'Flag unusual rises', who:'Consumer compliance analysts', vol:'210 banks and 60 issues, quarterly', sys:'Spreadsheet, case system',
   notes:'Analysts compare this quarter’s counts by bank and issue with earlier quarters, looking for rises. A bank with ten times the customers gets ten times the complaints, but the Bank does not hold customer numbers by product.',
   pain:'The largest banks always top the list, and real rises at small banks are lost in the noise.',
   p:'check structured mid mid', alt:'shape:predict', best:'anomaly', ok:'predict rules', auto:'review',
   why:'Anomaly detection fits, but only on complaints per customer. Without each bank’s customer numbers, any flag mostly measures size. Park it until that data is agreed.',
   disc:[['No denominator','Customer numbers by product are not in any filing the Bank receives.','Blocked: it needs a new data request to banks, which takes a policy decision.'],['Tiny numbers','Most small banks get fewer than five complaints a quarter.','Group small banks, or one complaint looks like a spike.']],
   fv:'low high', reality:'High value if it worked, low feasibility without customer numbers. Park it, and name the data request as the blocker.',
   metric:'Rises flagged that examiners confirm, and problems found later that were not flagged', g:'threshold sampling', hyp:'Examiners pointed at the rises that matter, at banks of any size.', data:'Coded complaints by bank and issue, and customer numbers by product, which the Bank does not yet hold.'},
  {n:'Explain what lies behind a rise', who:'Consumer compliance analysts', vol:'About 15 rises a quarter, 30 to 200 complaints each', sys:'Case system, bank responses',
   notes:'For each rise worth a look, an analyst reads the complaints and the banks’ responses to say what is happening: a new fee, a system change, a branch closing. The note goes to the bank’s examiners.',
   pain:'The reading takes a week a quarter, so only the largest rises get a note.',
   p:'summarize text mid mid', best:'summarize', ok:'classify extract', auto:'review',
   why:'Summarise the complaints behind each rise into the common story, with example quotes and dates, for the analyst to check and send. The examiners decide what to do about it.',
   disc:[['Examiners decide','The note tells examiners where to look; it is not a finding.','Keep: the analyst checks every note before it goes.'],['Personal details','Narratives include account numbers and health details.','Privacy: keep personal details out of the note.']],
   fv:'high mid', reality:'Quick to do on text already in the case system. Medium value: every rise explained, not just the largest.',
   metric:'Rises with a note to examiners, and analyst hours per note', g:'privacy sampling', hyp:'A note on every rise within two weeks of quarter end.', data:'Coded complaints, bank responses, past notes to examiners.'},
  {n:'Write the quarterly trend report', who:'Consumer compliance manager', vol:'Four reports a year, about 10 pages each', sys:'Word, spreadsheet charts',
   notes:'Each quarter the manager writes a short report for examiners and senior supervisors: the main trends, the banks to watch and charts by product.',
   pain:'Two days a quarter. The charts are rebuilt by hand each time.',
   p:'draft text low mid', best:'draft', ok:'summarize', auto:'review',
   why:'Four reports a year do not justify a tool. The general assistant can help with a first draft, and the charts can be saved as a template.',
   disc:[['Four a year','Four reports a year, two days each.','Volume: not worth a dedicated tool.'],['Charts by hand','The charts are rebuilt from scratch every quarter.','Save them as a template linked to the coded data.']],
   fv:'high low', reality:'Easy, and too small to build for.',
   metric:'Days to produce the report', g:'sampling', hyp:'The report done in a day, with charts that update themselves.', data:'The quarter’s coded complaints and notes.'},
 ]},

 {fn:'supervision', area:'sup-reports',
  proc:{id:'mergers', name:'Bank merger applications', d:'Check the application is complete, read public comments, test the effect on competition and write the recommendation.', rating:1, why:'About six applications a year, each a legal and supervisory judgment under public scrutiny. The competition screen is a rule worth building once; the rest stays with people.'},
  intro:'When two banks want to merge, they must ask permission. The Bank checks the application, hears from the public, tests the effect on competition in each local market and recommends a decision. A handful a year, each closely watched. Walk an application.',
  steps:[
  {n:'Check the application is complete', who:'Applications analysts', vol:'About 6 applications a year', sys:'Application forms, checklist, email',
   notes:'The analyst checks the application against a checklist of required forms, financial statements and plans, and writes to the banks for anything missing before the clock starts.',
   pain:'A day or two per application. Little measurable cost.',
   p:'check text low mid', best:'extract', ok:'rules', auto:'review',
   why:'Six a year against a fixed checklist. The checklist itself is the right tool.',
   disc:[['Six a year','About six applications arrive a year.','Volume: not worth a tool.'],['The same gaps','The same three items are missing from most applications.','Put them at the top of the guide banks read before filing.']],
   fv:'high low', reality:'Easy, and too rare to be worth a tool.',
   metric:'Days to a complete application', g:'logging', hyp:'Applications complete on arrival.', data:'The checklist and past applications.'},
  {n:'Read the public comments', who:'Applications analysts and community affairs staff', vol:'Usually under 20 comments; 1,400 for one contested merger last year', sys:'Email, comment log',
   notes:'The public can comment on a proposed merger, and community groups often do, about branch closures and lending in poorer neighbourhoods. Staff read every comment, group the concerns and ask the banks to answer each one.',
   pain:'Most years it takes a day. Last year one contested merger drew 1,400 comments, many of them form letters, and took two people five weeks.',
   p:'summarize text low high', alt:'shape:route', best:'summarize classify', ok:'extract', auto:'assist',
   why:'Group comments by concern, set identical form letters aside with a count, and summarise the distinct points with quotes. Staff read every distinct comment, because each concern needs a considered answer on the public record.',
   disc:[['On the public record','Comments, and how they were answered, become part of the public decision.','Risk: a person reads every distinct comment; assist only.'],['Form letters','Most of the 1,400 were five form letters with small changes.','Grouping identical letters is most of the time saved.']],
   fv:'high mid', reality:'Easy to help with when a surge comes. High stakes, so assist only.',
   metric:'Staff weeks per contested application, and concerns missed in the banks’ answers', g:'logging sampling escalation', hyp:'A contested merger’s comments grouped and summarised in a week, with every concern answered.', data:'Past comment logs and the concerns raised.'},
  {n:'Test the effect on competition', who:'Competition analysts', vol:'About 6 analyses a year, 4 to 30 local markets each', sys:'Branch deposit data, market definitions, spreadsheet',
   notes:'For each local banking market where both banks have branches, analysts calculate market shares from branch deposit data and a standard concentration measure, before and after the merger. Markets over a threshold get a closer look.',
   pain:'A week per application rebuilding the same spreadsheet. A formula error last year was caught only in legal review.',
   p:'check structured low high', best:'rules', ok:'fix', auto:'review', autoOk:'assist',
   why:'The concentration screen is a fixed calculation on structured data. Build it once, tested, so every application runs the same way. The closer look at markets over the threshold stays with analysts.',
   disc:[['A published method','The screen follows a published method that banks also run.','Rule: one tested calculation, the same every time.'],['The spreadsheet error','Last year’s error came from a copied formula.','Feasibility: a small build that is easy to test.']],
   fv:'high mid', reality:'Plain engineering with a medium prize: a week per application, and no formula errors.',
   metric:'Days per competition analysis, and calculation errors found in review', g:'logging sampling', hyp:'The screen runs in an hour, the same way every time.', data:'Branch deposit data, market definitions, the screen’s thresholds.'},
  {n:'Write the recommendation', who:'Senior applications officer', vol:'About 6 recommendations a year', sys:'Word, analyses, legal review',
   notes:'The officer weighs the competition analysis, the banks’ condition from their examinations, the public comments and the banks’ record in their communities, and recommends approval, approval with conditions or denial to the president.',
   pain:'Three weeks of drafting and legal review per application.',
   p:'decide text low high', best:'recommend', ok:'retrieve summarize', auto:'assist',
   why:'Pull past decisions on similar mergers and the conditions attached to them. The officer weighs the evidence and writes the recommendation, and the president decides.',
   disc:[['Legal weight','Merger decisions are published and can be challenged.','Risk: assist only, and every source cited.'],['Past conditions','Conditions attached to past approvals are scattered across old decision letters.','Retrieval over past decisions is the narrow, useful help.']],
   fv:'mid mid', reality:'Medium value and high stakes. A narrow assist: finding precedent.',
   metric:'Weeks from complete application to recommendation', g:'logging escalation', hyp:'Every relevant past decision in front of the officer in minutes.', data:'Past merger decisions, their conditions and legal reviews.'},
 ]},

 {fn:'supervision', area:'sup-reports',
  proc:{id:'stresstest', name:'Stress test submission review', d:'Check each larger bank’s stress test submission for completeness and consistency, read its methods, and challenge the outliers.', rating:2, why:'Nine large submissions a year. The consistency checks are rules worth building, reading help waits on the approved environment, and the challenge is a supervisory judgment.'},
  intro:'Each year the nine largest banks in the district project their losses and capital under a severe scenario and send the results to the Bank. Staff check the numbers, read the methods and challenge whatever looks too good. Walk a submission season.',
  steps:[
  {n:'Check completeness and consistency', who:'Stress test analysts', vol:'9 submissions a year, about 4,000 data fields each', sys:'Submission templates, validation spreadsheet, quarterly filings',
   notes:'Analysts check each submission has every schedule, that totals add up, and that starting balances match the bank’s latest quarterly filing. The checks are written down, but they are run in a spreadsheet by copying each bank’s data in.',
   pain:'Two analyst-weeks per season, and a resubmission means doing it all again.',
   p:'check structured mid mid', best:'rules', ok:'anomaly', auto:'auto', autoOk:'review',
   why:'Completeness and consistency checks are rules, already written down. Run them automatically on every submission and resubmission, and send the failures to the bank.',
   disc:[['The rules exist','Every check is listed in the instructions banks receive.','Feasibility: automation, not research.'],['Resubmissions','Most banks resubmit at least once.','Run the checks on every version, automatically.']],
   fv:'high mid', reality:'Plain engineering on structured data. Medium value in analyst weeks.',
   metric:'Analyst days on validation, and days from submission to clean data', g:'logging rollback', hyp:'Every submission and resubmission checked within an hour.', data:'The submission templates, the validation rules, the quarterly filings.'},
  {n:'Read the methods documents', who:'Stress test analysts and model specialists', vol:'9 banks, about 600 pages each', sys:'PDF documents, last year’s notes',
   notes:'Each bank sends documents explaining its models, assumptions and changes since last year. Specialists read them to find what changed and what needs questioning, comparing with last year’s documents by hand.',
   pain:'Three weeks of reading in a tight season. Changes buried in an appendix have been missed.',
   p:'summarize text mid mid', alt:'shape:check', best:'summarize', ok:'extract retrieve', auto:'review',
   why:'Compare this year’s documents with last year’s and summarise what changed in each model and assumption, with page references, so specialists read in full where it matters.',
   disc:[['Confidential and long','The documents are confidential supervisory information and commercially sensitive.','Prepare: the approved environment is not yet set up for documents this size.'],['Tables as pictures','Some banks send key tables as images inside PDFs.','Prepare: ask banks for tables in a readable format.']],
   fv:'mid high', reality:'High value in a tight season. Medium feasibility until the approved environment and readable tables are in place.',
   metric:'Weeks to a list of changes, and changes found late', g:'privacy sampling logging', hyp:'A full list of changes in each bank’s methods within a week of submission.', data:'This year’s and last year’s methods documents, past change notes.'},
  {n:'Challenge the outliers', who:'Senior supervisors and model specialists', vol:'9 banks, about 30 portfolios each', sys:'Submission data, benchmark models, peer comparisons',
   notes:'Specialists compare each bank’s projected losses by portfolio with its peers and with the Bank’s own benchmark models. Where losses look too low, they write challenge questions, and if the answers do not satisfy, the result can limit what the bank may pay its shareholders.',
   pain:'The peer comparisons are built by hand, so specialists look closely at only a few portfolios per bank.',
   p:'check structured mid high', alt:'shape:decide', best:'anomaly', ok:'predict recommend', auto:'assist',
   why:'Flag the portfolios where a bank’s projections sit furthest from its peers and the benchmark, ranked, so specialists see all of them. The challenge and what follows are supervisory judgments that stay with people.',
   disc:[['Consequences for banks','The outcome can limit a bank’s dividends.','Risk: assist only; every challenge is a person’s decision.'],['Few peers','With nine banks, some portfolios have only two peers.','Lean on the benchmark models where peers are too few.']],
   fv:'mid high', reality:'High value and high stakes. Assist only.',
   metric:'Portfolios compared per bank, and challenges that changed a result', g:'logging escalation sampling', hyp:'Every portfolio compared with peers and the benchmark, not just a few.', data:'Submission data, the benchmark models’ results, past challenges.'},
 ]},

 /* ---------------- Cash & payment operations ---------------- */
 {fn:'cashops', area:'cash-payments',
  proc:{id:'sanctions', name:'Sanctions screening alerts', d:'Screen outgoing payments against sanctions lists, clear the false alerts and escalate the rare possible match.', rating:4, why:'High alert volume, almost all false, with a measured cost in analyst hours and payment delays. Tuning is engineering, clearing alerts is a strong assist, and a possible match is a legal decision.'},
  intro:'Every payment the Bank sends for itself and for the government accounts it holds is screened against sanctions lists before it leaves. Thousands of alerts a month, almost all of them a name that only looks like a listed one. Missing the real one is very serious. Walk an alert.',
  steps:[
  {n:'Tune the screening and the cleared-names list', who:'Sanctions compliance officers', vol:'About 30,000 payments and 2,400 alerts a month', sys:'Screening system, list feeds, cleared-names spreadsheet',
   notes:'The screening system compares every payment’s names and addresses with the sanctions lists, which change several times a week. Names already cleared, such as a regular supplier whose name resembles a listed one, are kept in a spreadsheet that is loaded into the system by hand once a month.',
   pain:'Four alerts in ten are names cleared before, firing again because the spreadsheet is a month behind.',
   p:'check structured high high', best:'rules', ok:'anomaly', auto:'review', autoOk:'assist',
   why:'Load each cleared name into the screening system the day it is cleared, with an expiry date and a record of who cleared it, and test match thresholds against past alerts. Configuration, not AI.',
   disc:[['Repeat alerts','Four alerts in ten repeat a name cleared earlier.','Fix first: a same-day, logged cleared-names list.'],['Thresholds need evidence','Loosening the match threshold cuts alerts, but supervisors expect a tested reason.','Rule: change thresholds only after testing on past true matches, and log why.']],
   fv:'high high', reality:'Plain engineering with a high prize: four alerts in ten gone.',
   metric:'Alerts per month, and repeat alerts on cleared names', g:'logging rollback sampling', hyp:'Alerts cut by 40% without missing a known true match.', data:'Two years of alerts with outcomes, the cleared-names list, past true matches.'},
  {n:'Clear the false alerts', who:'Sanctions analysts', vol:'About 2,400 alerts a month', sys:'Screening system, payment messages, sanctions list entries',
   notes:'For each alert, an analyst compares the payment details with the list entry: full name, date of birth, country, address, the bank involved. Almost all are cleared in a few minutes, and the payment waits until they are.',
   pain:'Six analysts clear alerts all day, and payments wait up to four hours at busy times.',
   p:'check text high high', alt:'shape:decide', best:'extract anomaly', ok:'recommend rules', auto:'assist',
   why:'Set the payment’s details beside the list entry, mark which ones match and which differ, and rank alerts so the likeliest true matches come first. An analyst clears every alert; nothing is cleared automatically.',
   disc:[['A miss is very serious','Sending a payment to a sanctioned person breaks the law and can bring large penalties.','Risk: a person clears every alert; assist only.'],['Thin details','Many payment messages carry only a name and a country.','Prepare: ask the government accounts to send full details, which clears alerts faster.']],
   fv:'mid high', reality:'High value and high stakes. Assist only, with every decision logged.',
   metric:'Minutes per alert, payment delays, and true matches found by later review', g:'logging escalation sampling threshold', hyp:'Minutes per alert halved, with no true match missed.', data:'Two years of alerts with their outcomes, the list entries, payment messages.'},
  {n:'Escalate a possible true match', who:'Chief compliance officer', vol:'About 3 cases a year', sys:'Case file, legal counsel, reports to the authorities',
   notes:'When an analyst cannot rule out a match, the payment is held and the case goes to the chief compliance officer, who decides with legal counsel whether to block or reject it, and reports it to the authorities within the legal deadline.',
   pain:'No measurable cost. It is rare, and it is done with great care.',
   p:'decide text low high', best:'recommend', ok:'retrieve', auto:'assist',
   why:'Three cases a year, each a legal decision. A clear checklist and a template for the report to the authorities are the right size. No tool.',
   disc:[['Three a year','About three cases a year.','Volume: not worth a tool.'],['The deadline','The report to the authorities has a fixed legal deadline.','Keep a one-page checklist with the deadline and who signs.']],
   fv:'high low', reality:'Too rare and too serious for a tool. A checklist is the right size.',
   metric:'Reports made within the legal deadline', g:'logging escalation', hyp:'Every possible match reported on time, with a complete file.', data:'The checklist and past case files.'},
 ]},

 {fn:'cashops', area:'cash-payments',
  proc:{id:'settlement', name:'Settlement reconciliation', d:'Match the day’s settlement entries across systems, chase late manual adjustments and investigate the breaks that are left.', rating:3, why:'Daily, structured and already in systems. Matching is a rule, the largest source of breaks is a broken hand-off, and only the real breaks need a person, with help.'},
  intro:'At the end of every day, the settlement balances of 300 banks must agree across the payment system, the ledger and the cash system. Every difference is a question about central bank money. Walk the close.',
  steps:[
  {n:'Match the day’s entries across systems', who:'Settlement analysts', vol:'About 9,000 entries a day across three systems', sys:'Payment system, general ledger, cash system, spreadsheets',
   notes:'After the payment system closes, analysts export the day’s entries from three systems and match them in spreadsheets by amount, account and reference. Entries that do not match become breaks.',
   pain:'Two analysts spend three hours every evening matching, and the spreadsheet formulas break whenever a file layout changes.',
   p:'check structured high mid', best:'rules', ok:'anomaly', auto:'auto', autoOk:'review',
   why:'Matching structured entries by amount, account and reference is a rule. A reconciliation tool does it in minutes and shows only the breaks. No AI is needed.',
   disc:[['A tool already owned','Finance already uses a reconciliation tool for supplier payments.','Feasibility: extend it, rather than buy.'],['One reference differs','The cash system uses its own reference.','Prepare: map the references once.']],
   fv:'high high', reality:'Plain engineering with a high prize: hours back every evening, and fewer errors.',
   metric:'Analyst hours on matching, and time from close to a reconciled position', g:'logging rollback', hyp:'Matching done in minutes after close, every day.', data:'The three systems’ daily exports and a reference map.'},
  {n:'Chase late manual adjustments', who:'Settlement analysts', vol:'About 25 breaks a day, a third from late adjustments', sys:'Phone, email, ledger',
   notes:'A third of breaks come from manual adjustments that other teams post to the ledger after the cut-off. Analysts ring round the teams to find out who posted what, and why.',
   pain:'An hour a day on the phone, and some evenings the close waits for a team that has gone home.',
   p:'coordinate text high mid', alt:'input:structured', best:'fix', ok:'rules agent', auto:'review',
   why:'These breaks exist because the cut-off is not enforced. Set one cut-off for manual adjustments, with a short log for real exceptions, and the calls stop. Fix the hand-off before any tool.',
   disc:[['Two teams','Two teams post almost all the late adjustments.','Fix first: agree the cut-off with those two teams.'],['No reasons','Nobody records why a late adjustment was needed.','Capture a reason with every late adjustment.']],
   fv:'high mid', reality:'A process fix, quick to do, with a medium prize: a third of breaks gone.',
   metric:'Breaks from late adjustments, and evenings the close is delayed', g:'logging', hyp:'Late-adjustment breaks cut from eight a day to one.', data:'A month of breaks with their causes.'},
  {n:'Investigate the remaining breaks', who:'Senior settlement analysts', vol:'About 15 breaks a day', sys:'Payment system, ledger, cash system, break log',
   notes:'For each remaining break, a senior analyst traces the entries, works out the cause and, if a bank’s balance is wrong, proposes a correction for a supervisor to approve.',
   pain:'A break carried overnight means a bank’s balance may be wrong at the next morning’s opening.',
   p:'check structured mid high', best:'anomaly', ok:'rules recommend', auto:'assist',
   why:'Compare each break with past breaks to suggest the likely cause, and flag the ones unlike anything before. The analyst investigates and a supervisor approves every correction, because it moves central bank money.',
   disc:[['Moving money','A correction changes a bank’s balance at the central bank.','Risk: a person approves every correction.'],['Causes are logged','Two years of breaks are logged with their causes.','Data: a good base for suggesting causes.']],
   fv:'mid high', reality:'High value and high stakes. Assist only, once matching and the cut-off are fixed.',
   metric:'Breaks carried overnight, and corrections reversed', g:'logging escalation sampling', hyp:'No break carried overnight without a known cause.', data:'Two years of breaks with their causes and corrections.'},
 ]},

 {fn:'cashops', area:'cash-currency',
  proc:{id:'coinorders', name:'Coin and note orders from banks', d:'Take banks’ orders, check them for errors, schedule the armoured shipments and reorder coin from the national mint.', rating:3, why:'Daily orders from 300 banks, mostly through a portal already. The useful AI here is not a language model: anomaly flags on orders and, once its constraints are written down, a scheduling model for the trucks.'},
  intro:'Three hundred banks order notes and coin from the Bank for their branches and cash machines. Coin is heavy, trucks are limited, and a wrong or late order leaves a bank short. Walk an order from the portal to the loading dock.',
  steps:[
  {n:'Take orders from banks', who:'Cash services staff', vol:'About 4,500 orders a month, 15% by email or phone', sys:'Ordering portal, email, phone, vault system',
   notes:'Banks place orders on the ordering portal by 2pm for next-day delivery. About 40 smaller banks still email or phone, and staff key their orders into the portal for them.',
   pain:'About one keyed order in thirty has an error, and late orders taken by phone cannot always be filled.',
   p:'coordinate text high low', alt:'shape:extract', best:'fix', ok:'extract rules', auto:'auto', autoOk:'review',
   why:'The portal already exists. Move the last 40 banks onto it, with help for the few who need it, and hold everyone to the cut-off. Reading orders out of emails would keep the wrong habit alive.',
   disc:[['Forty banks','Forty small banks send 15% of orders by email and phone.','Fix first: a training call and a simple login for each.'],['The cut-off','Phone orders after 2pm are taken as a favour.','Rule: the cut-off applies to everyone, with a named exception path.']],
   fv:'high mid', reality:'A process fix, quick to do. Medium value: keying removed and fewer short deliveries.',
   metric:'Orders keyed by staff, and keying errors', g:'logging', hyp:'Every order placed by the bank itself on the portal.', data:'The list of banks ordering by email or phone.'},
  {n:'Check orders for errors and unusual demand', who:'Cash services staff', vol:'About 4,500 orders a month', sys:'Ordering portal, order history',
   notes:'Staff glance over each day’s orders for mistakes, such as an extra zero, and for banks ordering far more than usual, which can mean a local rush for cash or a fraud. Only the largest orders get a real look.',
   pain:'Two orders with an extra zero were shipped last year, and a sudden rise at three banks before a storm was noticed only afterwards.',
   p:'check structured high mid', best:'anomaly', ok:'rules predict', auto:'review',
   why:'Compare every order with the bank’s own history and the weekly forecast, and flag the unusual ones for a call to the bank before anything ships. Staff decide what to do.',
   disc:[['Ten years of orders','Order history goes back ten years by bank and denomination.','Data: ready.'],['Not every spike is wrong','Storms and holidays raise orders for good reasons.','Feed in the calendar and weather alerts, or staff will learn to ignore the flags.']],
   fv:'high mid', reality:'Quick to do on ready data. Medium value: errors caught, and early warning of unusual demand.',
   metric:'Orders shipped in error, and unusual orders flagged before shipping', g:'threshold sampling', hyp:'No order with an extra zero leaves the vault.', data:'Order history, the weekly forecast, holiday and weather calendars.'},
  {n:'Schedule armoured shipments', who:'Shipment dispatcher', vol:'About 220 deliveries a day, 18 armoured trucks', sys:'Spreadsheet, carrier contract, phone',
   notes:'One dispatcher builds the next day’s truck routes from the orders. Coin is heavy, so weight limits bite before value limits. Which branches have a dock a large truck can use, and which need two guards, is known only to the dispatcher.',
   pain:'Routes take three hours every afternoon. When the dispatcher is away, trucks run overweight or arrive at docks they cannot use.',
   p:'allocate tacit high mid', alt:'input:structured', best:'optimize', ok:'predict fix', auto:'review',
   why:'Routing the trucks is an optimisation problem, but its key constraints are in one person’s head. Write down every branch’s dock, guard and time-window rules first; then a scheduling model can build routes for the dispatcher to adjust.',
   disc:[['One dispatcher','The constraints live with one person, who retires in two years.','Capture first: a branch constraints table, filled in with the dispatcher.'],['Weight, not value','Coin weight, not value, sets most truck limits.','The model must plan by weight and value together.']],
   fv:'mid high', reality:'High value and a mature technique, but nothing can be planned until the constraints are written down.',
   metric:'Hours to build routes, and overweight or failed deliveries', g:'rollback sampling', hyp:'Routes built in half an hour, by anyone, with no failed deliveries.', data:'A branch constraints table, truck capacities, the carrier contract, order history.'},
  {n:'Reorder coin from the national mint', who:'Cash operations manager', vol:'One order a month', sys:'Vault system, spreadsheet, mint ordering system',
   notes:'Once a month the manager orders new coin from the national mint, using the vault’s stock levels and the coming weeks’ forecast. Coin takes six weeks to arrive, and vault space is limited.',
   pain:'Little measurable cost. The vault ran low on one coin once last year.',
   p:'predict structured low mid', best:'predict', ok:'optimize', auto:'review',
   why:'Twelve orders a year, built on the weekly forecast that already exists. A reorder level in the spreadsheet is the right size, not a new model.',
   disc:[['Twelve a year','One order a month.','Volume: not worth a tool of its own.'],['The forecast exists','The weekly order forecast already covers coin.','Reuse it, and add a reorder level for each coin.']],
   fv:'high low', reality:'Easy, and too small to build for.',
   metric:'Weeks the vault runs short of any coin', g:'sampling', hyp:'No coin shortage in the vault.', data:'Vault stock levels and the weekly forecast.'},
 ]},

 {fn:'cashops', area:'cash-currency',
  proc:{id:'counterfeit', name:'Counterfeit note reports', d:'Log the suspect notes banks send in, examine each one, and report counterfeits to the police.', rating:2, why:'Steady but modest volume of physical evidence. Vision can help specialists match known counterfeits; the paper form and the police report are a fix and plain engineering.'},
  intro:'Banks and the Bank’s own sorting machines catch notes that might be fake. Each one is evidence: logged, examined by a specialist and reported to the police with a chain of custody. Walk a suspect note.',
  steps:[
  {n:'Log suspect notes as they arrive', who:'Counterfeit desk clerks', vol:'About 250 notes a month', sys:'Paper submission forms, evidence log, safe',
   notes:'Banks send suspect notes in sealed bags with a handwritten paper form: where the note was found, who passed it, and when. Clerks key each form into the evidence log and record the chain of custody.',
   pain:'A third of forms are missing details the police need, such as the date or the depositor, and clerks phone the bank to get them.',
   p:'extract media mid mid', alt:'shape:coordinate', best:'extract', ok:'vision fix', auto:'review',
   why:'Read the handwritten forms into the evidence log, with a clerk confirming each one. Better still, move the form online so the police fields cannot be left blank, and read only the paper that still comes.',
   disc:[['Handwriting','Most forms are filled in by hand in a hurry at a branch counter.','Prepare: expect low confidence, and confirm every field.'],['An online form','An online form would make the police fields required.','Fix: offer it to banks, and keep paper for those who need it.']],
   fv:'mid mid', reality:'Medium on both. Reading the forms is possible; an online form would remove most of the problem.',
   metric:'Forms missing police details, and minutes per log entry', g:'threshold logging', hyp:'Every note logged the day it arrives, with the details the police need.', data:'Past forms with their log entries.'},
  {n:'Examine each suspect note', who:'Currency specialists', vol:'About 250 notes a month', sys:'Magnifiers, ultraviolet lamps, image scanner, reference library',
   notes:'Specialists examine each note by hand, under magnification and ultraviolet light, to decide whether it is genuine. Counterfeits are matched to known “families” printed by the same source, so the police can link cases.',
   pain:'Matching a note to a family means leafing through a reference library of 400 families. A verdict takes two to four weeks.',
   p:'physical media mid high', alt:'shape:check', best:'vision', ok:'retrieve', auto:'assist',
   why:'Scan each note and match it against images of known families, ranked, for the specialist to confirm. The specialist examines the note in hand and makes every call, because it becomes evidence.',
   disc:[['Evidence in court','A specialist may have to testify to the finding.','Risk: the specialist decides; the match only points where to look.'],['Images exist','Every confirmed counterfeit has been scanned for ten years.','Data: a labelled image library already exists.']],
   fv:'mid high', reality:'High value and high stakes. A specialist vision tool, used in assist mode.',
   metric:'Days to a verdict, and notes matched to a known family', g:'logging escalation sampling', hyp:'A verdict within a week, with more cases linked to a known source.', data:'Scanned images of confirmed counterfeits by family.'},
  {n:'Report counterfeits to the police', who:'Counterfeit desk clerks', vol:'About 200 reports a month', sys:'Evidence log, police reporting form, email',
   notes:'For each counterfeit, a clerk fills in the police reporting form with the note’s details, its family and where it was found, copying from the evidence log, and writes to the bank with the result.',
   pain:'Fifteen minutes of copying between screens per report, and the letter to the bank is often weeks late.',
   p:'draft structured high mid', best:'rules', ok:'draft agent', auto:'review', autoOk:'auto',
   why:'Every field on the police form is already in the evidence log. Fill the form and the bank’s letter from the log automatically, for a clerk to send. Engineering, not AI.',
   disc:[['All in the log','The police form asks for nothing the log does not hold.','Feasibility: a template filled from fields.'],['Secure email only','The police accept reports by secure email only.','Keep it simple: generate the form, and a clerk sends it.']],
   fv:'high mid', reality:'Plain engineering. Medium value: clerk time saved and faster letters to banks.',
   metric:'Minutes per report, and days to the bank’s letter', g:'logging', hyp:'Reports and letters out the day the verdict is recorded.', data:'The evidence log and the police form.'},
 ]},

 {fn:'cashops', area:'cash-resilience',
  proc:{id:'incidentcomms', name:'Incident communications', d:'Get the first notice approved and out, send it to every bank, and write the summary after the incident.', rating:2, why:'About a dozen incidents a year, with every minute watched. Pre-approved templates and a working contact list do more than any AI; the final summary is a careful assist.'},
  intro:'When a payment system the Bank runs is disrupted, 300 banks need to know quickly and accurately what is happening and what to do. About a dozen times a year, the clock starts. Walk an incident from the first alarm to the final summary.',
  steps:[
  {n:'Get the first notice approved and out', who:'Payments operations manager', vol:'About 12 incidents a year', sys:'Email, phone, chat',
   notes:'When a system fails, the operations manager writes the first notice from scratch and gets it approved by the head of payments and by communications. During an outage, both are usually on other calls.',
   pain:'The first notice takes 50 minutes on average, against a 15-minute target. Banks hear about the outage from each other first.',
   p:'coordinate text low high', alt:'shape:draft', best:'fix', ok:'rules draft', auto:'assist',
   why:'Approve templates in advance for the ten most likely incidents, with blanks for the system, the time and the next update. The manager fills in the blanks and sends without waiting. No AI is needed, and nothing generated would be approved this fast.',
   disc:[['The same ten incidents','Ten incident types cover almost every notice in five years.','Fix first: approve ten templates in advance.'],['Approval is the delay','Most of the 50 minutes is spent waiting for two approvers.','Agree that a template notice needs no further approval.']],
   fv:'high high', reality:'A process fix with a high prize: banks hear from the Bank first, within 15 minutes.',
   metric:'Minutes from incident to first notice', g:'logging escalation', hyp:'The first notice out within 15 minutes, every time.', data:'Five years of past notices by incident type.'},
  {n:'Send the notice to every bank', who:'Payments operations staff', vol:'About 12 incidents a year, 3 to 6 notices each, 300 banks', sys:'Contact spreadsheet, email',
   notes:'Notices go by email from a spreadsheet of contacts at each bank, in batches, because the mail system limits the number of recipients. Banks change their contacts and rarely tell the Bank.',
   pain:'One contact in ten is out of date. After the last outage, eight banks said they never received a notice.',
   p:'coordinate structured low high', best:'rules', ok:'agent fix', auto:'review', autoOk:'assist',
   why:'A notification system that sends to every bank at once, records who has opened the notice and prompts calls to those who have not, from a contact list each bank confirms every quarter. Rules and integration, not AI.',
   disc:[['Stale contacts','One contact in ten is out of date.','Fix first: every bank confirms its incident contacts each quarter.'],['Proof of receipt','After an outage, banks dispute whether they were told.','Rule: log every delivery and every confirmation.']],
   fv:'high high', reality:'Plain engineering with a high prize: every bank told, with proof.',
   metric:'Banks reached within 15 minutes, and contacts out of date', g:'logging rollback', hyp:'Every bank reached within 15 minutes of the notice, with a record.', data:'A current contact list and delivery records.'},
  {n:'Write the summary after the incident', who:'Payments operations manager and communications staff', vol:'About 12 summaries a year', sys:'Chat logs, incident tickets, email, Word',
   notes:'Within five days of an incident, the Bank sends all 300 banks a summary: what happened, the effect on payments, and what will stop it happening again. The manager rebuilds the timeline from chat logs, tickets and memory.',
   pain:'A week of work each time, and the timelines sometimes disagree with what banks recorded.',
   p:'summarize text low high', alt:'shape:draft', best:'summarize', ok:'draft extract', auto:'assist',
   why:'Build a timeline from the chat log and tickets, and draft the summary for the manager to rewrite. Banks and their own supervisors act on it, so a person checks every statement before it goes out.',
   disc:[['Banks act on it','Banks report incidents to their own boards using this summary.','Risk: assist only; every line checked.'],['The record is in chat','The record of an incident is spread across three chat channels.','Keep one channel per incident, so the timeline is complete.']],
   fv:'high mid', reality:'Easy to help with and of medium value, but high stakes. Assist only.',
   metric:'Days to send the summary, and corrections asked for by banks', g:'logging sampling escalation', hyp:'A correct summary sent within three days.', data:'Chat logs, incident tickets, past summaries.'},
 ]},
];
